// #ece93f (6a993d6d5fdc2434e9ece93f) AC5 «הלקוח המדומה … מסמן את האירוע ברשומת הניסיון» — отметка видна менеджеру в шапке отчёта.
// Кейсы FLG-001, FLG-002. Роль — business testim (сессия bizt), десктоп. Только чтение, новых звонков нет.
// Источник истины — ответ get_candidate_report (attempt.content_flags); экран сверяется с ним. Заодно зафиксированы известные значения
// из записанных звонков: QA-CALL1-0411 — 01:13, QA-C10-2110-D3 — 00:35 (не меняются: это записанные события).
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';
import { candidateByName, viewById, openReportPage, ReportView } from './report-view-helpers';
import { listCandidates } from '../candidates/hiring-support';
import { clock, flagText } from '../admin-support/support-helpers';

const HASH = '#ece93f · #6a993d6d5fdc2434e9ece93f';
const FLAGGED = [
  { name: 'QA-CALL1-0411', time: '01:13' },
  { name: 'QA-C10-2110-D3', time: '00:35' },
];

const flagsOf = (v: ReportView) =>
  [...(v.attempt?.content_flags ?? [])]
    .filter((f) => !!f && typeof f.category === 'string')
    .sort((a, b) => (a.offset_ms ?? Infinity) - (b.offset_ms ?? Infinity));

test.describe(`Отчёт у менеджера — отметка оскорбительной/неуместной фразы кандидата в шапке (${HASH})`, () => {
  for (const f of FLAGGED) {
    test(`${f.name}: в шапке «בשיחה סומנה אמירה פוגענית של המועמד · ${f.time}», как в content_flags API @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const page = await asUser('bizt');
      await page.setViewportSize({ width: 1440, height: 900 });
      const api = await openWithApi(page, '/candidates');
      const id = await candidateByName(api, f.name);
      const flags = flagsOf(await viewById(api, id));
      expect(flags.length, `у ${f.name} в API нет content_flags — данные изменились`).toBeGreaterThan(0);
      expect(clock(flags[0].offset_ms ?? 0), 'время первой отметки в API').toBe(f.time);

      const meta = await openReportPage(page, id);
      // Источник: AC5 + ответ программиста 05.11 — «בשיחה סומנה אמירה פוגענית של המועמד · mm:ss», тип и время, без слов кандидата.
      const banner = meta.getByTestId('report-content-flags');
      await expect(banner).toBeVisible();
      const items = banner.locator('li');
      await expect(items, 'число отметок = числу в API').toHaveCount(flags.length);
      for (let i = 0; i < flags.length; i++) {
        await expect(items.nth(i)).toContainText(flagText(flags[i].category));
        if (flags[i].offset_ms !== null) await expect(items.nth(i)).toContainText(clock(flags[i].offset_ms!));
      }
      await expect(items.first()).toContainText(`${flagText('offensive')}`);
      await expect(items.first()).toContainText(f.time);
    });
  }

  test(`у кандидата без отметок баннера в шапке нет @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('bizt');
    await page.setViewportSize({ width: 1440, height: 900 });
    const api = await openWithApi(page, '/candidates');
    const all = await listCandidates(api);
    const flaggedNames = FLAGGED.map((f) => f.name);
    // Чистые по данным кандидаты: ищем среди списка по ответу API (готовый отчёт, content_flags пуст). Сначала — QA-данные 1310/1432.
    const ordered = [...all.filter((c) => /1432|HUM-1310/.test(c.full_name)), ...all.filter((c) => !/1432|HUM-1310/.test(c.full_name))].filter(
      (c) => !flaggedNames.includes(c.full_name),
    );
    let clean: { id: string; name: string } | null = null;
    for (const c of ordered.slice(0, 30)) {
      const v = await viewById(api, c.id);
      if (v.attempt && v.report?.status === 'ready' && flagsOf(v).length === 0) {
        clean = { id: c.id, name: c.full_name };
        break;
      }
    }
    expect(clean, 'не нашли кандидата с готовым отчётом без отметок (среди 30 первых)').not.toBeNull();

    const meta = await openReportPage(page, clean!.id);
    // Источник: AC5 — отметка есть только там, где событие было записано.
    await expect(meta.getByTestId('report-content-flags'), `${clean!.name}: баннера нет`).toHaveCount(0);
    await expect(meta).not.toContainText('סומנה אמירה');
  });
});
